extern "C" {
#   include <png.h>
#   ifdef _POSIX_C_SOURCE
#       undef _POSIX_C_SOURCE
#   endif
#   ifndef _AIX
#   ifdef _XOPEN_SOURCE
#       undef _XOPEN_SOURCE
#   endif
#   endif
}

